python3 - <<'PY'
from pathlib import Path
for p in sorted(Path('packages/sql-faker/src').rglob('*.php')):
 print(str(p).removeprefix('packages/sql-faker/src/'))
 for l in p.read_text().splitlines():
  if l.startswith(('use ', 'final class ', 'class ', 'interface ', 'enum ')): print(' '+l)
PY

