from pathlib import Path
import re
import subprocess
import json

root = Path('/Users/ab/Projects/ztd-query-php-sql-faker-deptrac')
package = root / 'packages/sql-faker'
src = package / 'src'
moves = {}
for name in '''Derivation GenerationException GenerationPlan LexicalException LexicalGrammar
LexicalKeywordIndex ProductionPattern RandomCharacters RandomStringGenerator
TerminationAnalyzer TerminationCost TokenJoiner'''.split():
    moves[f'Grammar/{name}.php'] = f'Generation/{name}.php'
for name in '''ArtifactDirectory GrammarParseException LexerSource LexicalProfileCheck
LexicalProfileWriter SourceCursor UnknownSymbolException UpstreamLexerSource'''.split():
    moves[f'Grammar/{name}.php'] = f'Compiler/{name}.php'
for dialect in ['MySql', 'PostgreSql', 'Sqlite']:
    for path in (src / dialect).glob('*.php'):
        if path.stem == 'StatementType':
            continue
        stage = 'Compiler' if any(part in path.stem for part in [
            'ProfileBuilder', 'ProfileCompiler', 'SourceParser', 'LexicalSamples', 'CoverageSamples'
        ]) else 'Generation'
        moves[f'{dialect}/{path.name}'] = f'{dialect}/{stage}/{path.name}'

def fqcn(path):
    return 'SqlFaker\\' + str(Path(path).with_suffix('')).replace('/', '\\')

names = {fqcn(old): fqcn(new) for old, new in moves.items()}
sources = {str(p.relative_to(src)): p.read_text() for p in src.rglob('*.php')}
old_classes = {}
for rel, content in sources.items():
    if re.search(r'^(?:final class|interface|enum) ', content, re.M):
        old_classes.setdefault(fqcn(rel).rsplit('\\', 1)[0], {})[Path(rel).stem] = fqcn(rel)

files = [root / p for p in subprocess.check_output(
    ['git', 'ls-files', '-z'], cwd=root
).decode().split('\0') if p]
for path in files:
    if path.suffix not in ['.php', '.md', '.json', '.neon', '.xml'] or not path.is_file():
        continue
    if path.name == 'AGENTS.md' or 'resources/ast' in str(path):
        continue
    content = original = path.read_text()
    rel = str(path.relative_to(src)) if path.is_relative_to(src) else None
    if rel in sources:
        old_namespace = fqcn(rel).rsplit('\\', 1)[0]
        new_namespace = fqcn(moves.get(rel, rel)).rsplit('\\', 1)[0]
        imports = []
        for short, old_class in old_classes.get(old_namespace, {}).items():
            target = names.get(old_class, old_class)
            if short == path.stem or target.rsplit('\\', 1)[0] == new_namespace:
                continue
            if re.search(r'(?<![\w\\])' + re.escape(short) + r'(?!\w)', content):
                if not re.search(r'^use .*\\' + re.escape(short) + r';$', content, re.M):
                    imports.append(f'use {target};')
        content = content.replace(f'namespace {old_namespace};', f'namespace {new_namespace};')
        if imports:
            content = content.replace(f'namespace {new_namespace};', f'namespace {new_namespace};\n\n' + '\n'.join(imports), 1)
    for old, new in names.items():
        content = re.sub(re.escape(old) + r'(?![\w\\])', lambda _: new, content)
        content = content.replace(old.replace('\\', '\\\\'), new.replace('\\', '\\\\'))

    destination = path
    if rel in moves:
        destination = src / moves[rel]
    elif path.is_relative_to(package / 'tests/Unit'):
        test_rel = str(path.relative_to(package / 'tests/Unit'))
        source_rel = test_rel.removesuffix('Test.php') + '.php'
        if source_rel in moves:
            target_rel = moves[source_rel].removesuffix('.php') + 'Test.php'
            destination = package / 'tests/Unit' / target_rel
            old_namespace = 'Tests\\Unit\\SqlFaker\\' + str(Path(test_rel).parent).replace('/', '\\')
            new_namespace = 'Tests\\Unit\\SqlFaker\\' + str(Path(target_rel).parent).replace('/', '\\')
            content = content.replace(f'namespace {old_namespace};', f'namespace {new_namespace};')
            extra_depth = len(Path(target_rel).parts) - len(Path(test_rel).parts)
            if extra_depth:
                content = content.replace("__DIR__ . '/../../../resources/", "__DIR__ . '/" + '../' * (3 + extra_depth) + 'resources/')
    if content != original or destination != path:
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(content)
        if destination != path:
            path.unlink()

Path('/tmp/sql-faker-layer-moves.json').write_text(json.dumps(moves, indent=2))
print(f'Moved {len(moves)} production files and their paired tests; updated references.')

